import gmpy2
from Crypto.Util.number import long_to_bytes

def connect_to_server():
    conn = remote('crypto.chal.csaw.io', 5000)
    response = conn.recvuntil(b'c2=', drop=True).decode()
    c2 = int(conn.recvline().decode().strip())
    conn.close()
    return response + f"c2={c2}"

def parse_parameters(data):
    params = {}
    for line in data.split('\n'):
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if value:
                try:
                    params[key] = int(value)
                except ValueError:
                    continue
    return params

def egcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = egcd(b % a, a)
        return (g, x - (b // a) * y, y)

def common_modulus_attack(n, e1, e2, c1, c2):
    # Ensure e1 and e2 are coprime
    g, s1, s2 = egcd(e1, e2)
    if g != 1:
        return None

    # If s1 negative, invert c1
    if s1 < 0:
        s1 = -s1
        c1 = gmpy2.invert(c1, n)
    # If s2 negative, invert c2
    if s2 < 0:
        s2 = -s2
        c2 = gmpy2.invert(c2, n)

    # Calculate message
    m = (pow(c1, s1, n) * pow(c2, s2, n)) % n
    return m

print("=== RSA Crypto Challenge Solver ===")
print("\nConnecting to server...")

try:
    server_data = connect_to_server()
    print("\nServer Response:")
    print(server_data)

    params = parse_parameters(server_data)
    print("\nParsed Parameters:")
